sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg("name", true);
        return;
    }

    var ga = new GlideAjax("BaseTableUtils");
	ga.addParam("sysparm_name", "checkNameDup");
	ga.addParam("sysparm_name_to_check", newValue);

	ga.getXML(handleNameResponse);
}

function handleNameResponse(response){
	var isDuplicate = response.responseXML.documentElement.getAttribute("answer");

	if (isDuplicate === "true"){
		g_form.clearValue("name");	
		g_form.showFieldMsg("name","This base name is already in use and cannot be duplicated, please change it.","error");				
	}else{
		g_form.hideFieldMsg("name", true);
	}
}
